#!/usr/bin/env bash
# verify-gapfill-web-tab-render (round 2): re-runs of the gap-round-2 trials (r0598, r0614, r0624, r0625, r0626) and
# their read-backs (r0618, r0627), each through gtr-run on a 2-core slot.
source /home/user/gtr/env.sh >/dev/null 2>&1
cd /home/user/gtr/lanes/web-tab-render
L="verify (verify-gapfill-web-tab-render, round 2)"
gtr-run --lane web-tab-render --tool abcjs --label "$L: re-run of r0598, abcjs 6.7.2 click, drag, keyboard and Editor gestures (trials A to E)" --input /home/user/gtr/lanes/web-tab-render/out/abcjs/S2n.written.abc -- node /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/scripts/abcjs_click_drag.cjs /home/user/gtr/lanes/web-tab-render/verify-gap2/abcjs-click-drag
gtr-run --lane web-tab-render --tool alphatab-monaco --label "$L: re-run of r0614, alphaTex edits in Monaco with the language server, alphaTab redraw, GP7 and alphaTex export" --input /home/user/gtr/lanes/web-tab-render/out/alphatex-from-truth/S2n.truth.atex -- node /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/scripts/alphatab_monaco_edit.cjs /lane/out/alphatex-from-truth/S2n.truth.atex /home/user/gtr/lanes/web-tab-render/verify-gap2/alphatab-monaco
gtr-run --lane web-tab-render --tool alphatab --label "$L: re-run of r0624, alphaTab 1.9.0 data-model string and fret edit, render, GP7 export" --input /home/user/gtr/inputs/S2n/S2n.gp5 -- node /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/scripts/alphatab_model_string_edit.cjs /home/user/gtr/lanes/web-tab-render/verify-gap2/alphatab-edit/S2n.string_edit
gtr-run --lane web-tab-render --tool vextab --label "$L: re-run of r0625, VexTab 4.0.5 editor mode string change by typing" -- node /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/scripts/vextab_editor_string_edit.cjs /home/user/gtr/lanes/web-tab-render/verify-gap2/vextab/editor_string_edit
gtr-run --lane web-tab-render --tool verovio --label "$L: re-run of r0626, Verovio 6.4.1 edit() set actions on MEI tab notes and one undo" --input /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/samples/verovio/S2n.truth.mei -- node /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/scripts/verovio_edit_tab.cjs /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/samples/verovio/S2n.truth.mei /home/user/gtr/lanes/web-tab-render/verify-gap2/verovio/S2n_edit
cd /home/user/gtr/lanes/web-tab-render/verify-gap2/alphatab-monaco && gtr-run --lane web-tab-render --tool alphatab --label "$L: re-run of r0618 on this round's re-run exports, read back with alphaTab 1.9.0 under Node" --input /home/user/gtr/lanes/web-tab-render/verify-gap2/alphatab-monaco/S2n.monaco_edited.gp --input /home/user/gtr/lanes/web-tab-render/verify-gap2/alphatab-monaco/S2n.monaco_edited.editor.atex --input /home/user/gtr/lanes/web-tab-render/verify-gap2/alphatab-monaco/S2n.monaco_capo2.gp -- bash -c "node /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/scripts/alphatab_node_model.cjs S2n.monaco_edited.gp readback edited_gp && node /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/scripts/alphatab_node_model.cjs S2n.monaco_edited.editor.atex readback edited_editor_atex && node /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/scripts/alphatab_node_model.cjs S2n.monaco_capo2.gp readback capo2_gp"
cd /home/user/gtr/lanes/web-tab-render && gtr-run --lane web-tab-render --tool alphatab --label "$L: re-run of r0627 on this round's re-run outputs (alphaTab read-back of the model-edited .gp; MEI to gtr-eval JSON)" --input /home/user/gtr/lanes/web-tab-render/verify-gap2/alphatab-edit/S2n.string_edit.edited.gp --input /home/user/gtr/lanes/web-tab-render/verify-gap2/verovio/S2n_edit.edited.mei -- bash -c "node /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/scripts/alphatab_node_model.cjs /home/user/gtr/lanes/web-tab-render/verify-gap2/alphatab-edit/S2n.string_edit.edited.gp /home/user/gtr/lanes/web-tab-render/verify-gap2/alphatab-edit/string_edit_readback string_edit_gp && python3 -I /home/user/blog/docs/guitar-tab-research/lanes/web-tab-render/scripts/mei_tab_to_json.py /home/user/gtr/lanes/web-tab-render/verify-gap2/verovio/S2n_edit.edited.mei /home/user/gtr/lanes/web-tab-render/verify-gap2/verovio/S2n_edit.edited.mei.json"
echo ALL-DONE
